import React, { useState } from "react";
import apiClient from "../../Services/ApiService";
import "./ForgotPassword.css";

const ForgotPassword = () => {
  const [step, setStep] = useState(1); // 1: request otp, 2: verify, 3: reset
  const [email, setEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const handleRequestOtp = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await apiClient.post("/forgot-password/request-otp", { email });
      setMessage(res.data.message || "Đã gửi OTP nếu email tồn tại.");
      setStep(2);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await apiClient.post("/forgot-password/verify-otp", { email, otp });
      setMessage(res.data.message || "OTP hợp lệ. Hãy đặt lại mật khẩu");
      setStep(3);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await apiClient.post("/forgot-password/reset", { email, otp, new_password: newPassword });
      setMessage(res.data.message || "Đặt lại mật khẩu thành công");
      setStep(4);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="forgot-password-page container py-5">
      <div className="row justify-content-center">
        <div className="col-md-6">
          <div className="card border-0 shadow-lg rounded-4">
            <div className="card-body p-4 p-md-5">
              <h2 className="fw-bold text-center mb-4" style={{color: "#ff6b35"}}>Quên mật khẩu</h2>

              {message && <div className="alert alert-success">{message}</div>}
              {error && <div className="alert alert-danger">{error}</div>}

              {step === 1 && (
                <form onSubmit={handleRequestOtp}>
                  <div className="mb-3">
                    <label className="form-label">Email</label>
                    <input type="email" className="form-control form-control-lg" value={email} onChange={(e)=>setEmail(e.target.value)} required />
                  </div>
                  <button className="btn btn-lg w-100 text-white" style={{backgroundColor: "#ff6b35"}} disabled={loading}>
                    {loading? "Đang gửi...": "Gửi OTP"}
                  </button>
                </form>
              )}

              {step === 2 && (
                <form onSubmit={handleVerifyOtp}>
                  <div className="mb-3">
                    <label className="form-label">Nhập OTP</label>
                    <input type="text" className="form-control form-control-lg" value={otp} onChange={(e)=>setOtp(e.target.value)} required />
                  </div>
                  <button className="btn btn-lg w-100 text-white" style={{backgroundColor: "#ff6b35"}} disabled={loading}>
                    {loading? "Đang kiểm tra...": "Xác minh OTP"}
                  </button>
                </form>
              )}

              {step === 3 && (
                <form onSubmit={handleResetPassword}>
                  <div className="mb-3">
                    <label className="form-label">Mật khẩu mới</label>
                    <input type="password" className="form-control form-control-lg" value={newPassword} onChange={(e)=>setNewPassword(e.target.value)} required />
                  </div>
                  <button className="btn btn-lg w-100 text-white" style={{backgroundColor: "#ff6b35"}} disabled={loading}>
                    {loading? "Đang cập nhật...": "Đặt lại mật khẩu"}
                  </button>
                </form>
              )}

              {step === 4 && (
                <div className="text-center">
                  <h4>✅ Hoàn tất!</h4>
                  <p>Bạn có thể đăng nhập bằng mật khẩu mới.</p>
                </div>
              )}

            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ForgotPassword;
